{
  "candidate_findings": [
    {
      "candidate_id": "rna_age_encoding",
      "candidate_sha256": "374c62888e3d5f544265ece87f785a14be69918bc83300c7164425708eca160d",
      "checks": [
        {
          "id": "age_joint",
          "target": "candidate",
          "claim": "The proposed H-reporter split and bead RNA encoding yield correctly paired pulse-window poly(A) RNA estimates and surface-target identities in the same individual cell, with a useful net gain.",
          "verdict": "transfer_not_established",
          "literature_refs": [
            {
              "source_id": "literature:f211796a4c3f6f48c7509dfe12d800a9092bed29306c869b5ec9756f4ba98161",
              "content_sha256": "e5afe60a5de458ca2d7885128684e086beaeef791b0036abb2b36c6a5072c4a8",
              "locator": "[b00010], K562 RNA-age experiment",
              "quote": "T–C conversions"
            },
            {
              "source_id": "literature:d473991d5c244a8d4423457ce5c0f4f74e19abaa6d25dae86283aca5f39dfc5a",
              "content_sha256": "81c59a3fcda7c7204b28b518598dc7088db348d785e649e9ea0f7f9f0ce44b28",
              "locator": "[b00031]-[b00035], PBMC and marrow phenotype experiments",
              "quote": "SOM3B"
            }
          ],
          "atlas_refs": [
            {
              "record_id": "cite_seq",
              "extraction_sha256": "3316ec994882191444a4d6ab13edaf3f97562e4d9ca00642b6f061000a34b824",
              "node_id": "illumina:cite_seq:operation:lyse_capture"
            }
          ],
          "reason": "NASC-seq demonstrates single-cell 4sU-dependent sequence encoding in K562/Jurkat cells; CITE-seq demonstrates ordinary RNA plus surface-reporter sequencing. No inspected source demonstrates their proposed H-tail split, matched-well copying, or improvement per input cell. Searches did not establish a completed exact joint assay; that is an unresolved coverage result, not a novelty finding. SOM3B already couples biosynthesis and immunophenotype using another instrument, so even the broader biological combination is not new."
        },
        {
          "id": "age_change",
          "target": "change:orthogonal_tail_and_pre_encoding_branch",
          "claim": "Replacing a reporter poly(A) tail with H and withdrawing the reporter branch before IAA improves joint recovery or attribution by removing chemistry exposure/capture competition.",
          "verdict": "not_found",
          "literature_refs": [
            {
              "source_id": "literature:b11de11cb22f3fbe80101ed276f64a570e8beed88591187022b6a0a9d30653bc",
              "content_sha256": "f594b6ea032669623778f0c7b6f51ff9f8f50b5b653ee43400b316a97ab15d28",
              "locator": "[b00008], Fig. 1a; same-cell separation with PEA protein readout",
              "quote": "supernatant"
            }
          ],
          "atlas_refs": [
            {
              "record_id": "cite_seq",
              "extraction_sha256": "3316ec994882191444a4d6ab13edaf3f97562e4d9ca00642b6f061000a34b824",
              "node_id": "illumina:cite_seq:operation:lyse_capture"
            }
          ],
          "reason": "The CITE-seq baseline co-captures poly(A) RNA and reporter DNA; SPARC already partitions mRNA beads from protein-containing supernatant. Neither establishes that IAA damages the candidate reporter or that shared capture is limiting. The proposed advantage, H exclusion, and transfer losses require the candidate factorial no-chemistry and routing comparison. A constructed shared-capture/IAA control is appropriately described as an engineered comparator, not an established closest joint method."
        },
        {
          "id": "age_routing",
          "target": "operation:proposal:rna_age_encoding:partition",
          "claim": "A single-cell lysate can deliver poly(A) RNA to retained beads and H reporters to a mapped supernatant with sufficient RNA recovery and reductant clearance for encoding.",
          "verdict": "transfer_not_established",
          "literature_refs": [
            {
              "source_id": "literature:b11de11cb22f3fbe80101ed276f64a570e8beed88591187022b6a0a9d30653bc",
              "content_sha256": "f594b6ea032669623778f0c7b6f51ff9f8f50b5b653ee43400b316a97ab15d28",
              "locator": "[b00008], Fig. 1a",
              "quote": "supernatant"
            },
            {
              "source_id": "literature:f211796a4c3f6f48c7509dfe12d800a9092bed29306c869b5ec9756f4ba98161",
              "content_sha256": "e5afe60a5de458ca2d7885128684e086beaeef791b0036abb2b36c6a5072c4a8",
              "locator": "[b00040], single-cell alkylation Methods",
              "quote": "STOP solution"
            }
          ],
          "atlas_refs": [],
          "reason": "SPARC supports separation of RNA beads from soluble protein at single-cell scale, not selective recovery of released H-DNA after reducing lysis. NASC-seq adds IAA before its DTT quench; it does not test this new pre-encoding reductant-release/wash interface. Mass balance of RNA, H-DNA and washes, residual-thiol effects, and checkerboard transfer errors remain decisive."
        },
        {
          "id": "age_rna_link",
          "target": "state_property:proposal%3Arna_age_encoding%3Abead_rna:capture_site",
          "claim": "RNA poly(A)/bead oligo(dT) hybridization can hold RNA through the candidate pre-IAA separation and washes until barcoded copying.",
          "verdict": "transfer_not_established",
          "literature_refs": [
            {
              "source_id": "literature:f211796a4c3f6f48c7509dfe12d800a9092bed29306c869b5ec9756f4ba98161",
              "content_sha256": "e5afe60a5de458ca2d7885128684e086beaeef791b0036abb2b36c6a5072c4a8",
              "locator": "[b00010] and [b00040], immobilization and processing",
              "quote": "magnetic beads"
            }
          ],
          "atlas_refs": [],
          "reason": "NASC-seq demonstrates oligo-dT immobilization and on-bead processing in its own lysis/support conditions. The additional reporter withdrawal and DTT-depletion washes are absent there. This noncovalent association and well confinement must be tested separately from the subsequent covalent barcode; loss before RT cannot be repaired computationally."
        },
        {
          "id": "age_alkylation",
          "target": "operation:proposal:rna_age_encoding:alkylate",
          "claim": "IAA treatment of the proposed RNA-bead substrate gives label-dependent sequence encoding without unacceptable RNA loss after upstream reporter release.",
          "verdict": "transfer_not_established",
          "literature_refs": [
            {
              "source_id": "literature:f211796a4c3f6f48c7509dfe12d800a9092bed29306c869b5ec9756f4ba98161",
              "content_sha256": "e5afe60a5de458ca2d7885128684e086beaeef791b0036abb2b36c6a5072c4a8",
              "locator": "[b00010] and [b00040]",
              "quote": "alkylation"
            },
            {
              "source_id": "literature:082748abf77ca0194c97489f6ad5c57eaf9361e1a7b8d8bc4a6f66aeb78b0cc9",
              "content_sha256": "9672cad7e5733af608212ee179c702560bf453f0e39116d06b4a38be524e1a02",
              "locator": "[b00030], MGI C4 comparison",
              "quote": "hard magnetic barcoded beads"
            }
          ],
          "atlas_refs": [],
          "reason": "The chemical encoding primitive is experimentally demonstrated in NASC-seq, including labeled/unlabeled cells and spike-in RNA. The modified well-coded support and release carryover are new. The benchmark independently shows that chemistry/platform compatibility is empirical; its TFEA failure on C4 beads does not contradict this IAA design. Test conversion and RNA recovery against untreated and no-label controls on the actual support."
        },
        {
          "id": "age_original_primitive",
          "target": "state:proposal:rna_age_encoding:encoded_rna",
          "claim": "The component premise that alkylated incorporated 4sU can cause recoverable T-to-C substitutions in single-cell RNA libraries is experimentally supported in NASC-seq.",
          "verdict": "supported_in_cited_setting",
          "literature_refs": [
            {
              "source_id": "literature:f211796a4c3f6f48c7509dfe12d800a9092bed29306c869b5ec9756f4ba98161",
              "content_sha256": "e5afe60a5de458ca2d7885128684e086beaeef791b0036abb2b36c6a5072c4a8",
              "locator": "[b00010], label controls and RT mechanism",
              "quote": "Reverse transcription"
            }
          ],
          "atlas_refs": [],
          "reason": "This verdict is restricted to NASC-seq K562/Jurkat experiments and their library chemistry, not to production of this exact proposed State. The sequencing observation is DNA substitutions after RT, from which a labeled-RNA fraction is inferred. The candidate correctly avoids calling the signal an exact birth time or a synthesis rate."
        },
        {
          "id": "age_covalent_reporter",
          "target": "state_property:proposal%3Arna_age_encoding%3Areporter_stock:link",
          "claim": "The complete custom reporter has the specified covalent antibody-DNA association and reducible release while retaining target binding.",
          "verdict": "not_found",
          "literature_refs": [
            {
              "source_id": "literature:1a6974cbc2fbb2ef798ff2cde54cfface7700355626ca69a5e446534b8826758",
              "content_sha256": "17170e847748ca17612bb02ef9d5677c8e4ddb9c50a1bd711d419713a97c0718",
              "locator": "Imported text [b00014]; candidate [b00013] locator is incorrect; host fulltext inaccessible",
              "quote": "disulfide link"
            }
          ],
          "atlas_refs": [],
          "reason": "The imported CITE-seq passage describes streptavidin-biotin attachment together with a disulfide; it does not demonstrate this complete all-covalent custom conjugate. A disulfide is not evidence that every link in the antibody-to-DNA association is covalent. The candidate already labels this exact property a hypothesis. Its cited disulfide phrase is at [b00014], not [b00013]. CITE-seq full-text host origin remains unverified in this investigation."
        },
        {
          "id": "age_reporter_copy",
          "target": "operation:proposal:rna_age_encoding:reporter_copy",
          "claim": "The H-complementary primer extends through the released target code and installs the matching B_j in a sequencing-compatible DNA library.",
          "verdict": "transfer_not_established",
          "literature_refs": [],
          "atlas_refs": [
            {
              "record_id": "cite_seq",
              "extraction_sha256": "3316ec994882191444a4d6ab13edaf3f97562e4d9ca00642b6f061000a34b824",
              "node_id": "illumina:cite_seq:operation:lyse_capture"
            }
          ],
          "reason": "CITE-seq establishes copying and indexing antibody DNA, but uses its poly(A) capture geometry. It does not validate H hybridization, full target copying after cleanup, or the proposed primer orientation. Sequence-defined template/primer controls and actual junction reads must verify both target and cell code in the same product."
        },
        {
          "id": "age_rna_copy",
          "target": "operation:proposal:rna_age_encoding:rna_copy",
          "claim": "RNA-derived library construction retains a cell code, UMI and enough transcript sequence for gene attribution and RNA-age inference.",
          "verdict": "transfer_not_established",
          "literature_refs": [
            {
              "source_id": "literature:f211796a4c3f6f48c7509dfe12d800a9092bed29306c869b5ec9756f4ba98161",
              "content_sha256": "e5afe60a5de458ca2d7885128684e086beaeef791b0036abb2b36c6a5072c4a8",
              "locator": "[b00040], library construction and existing NextSeq readout",
              "quote": "Smart-seq2"
            }
          ],
          "atlas_refs": [],
          "reason": "NASC-seq uses modified Smart-seq2 and post-tagmentation indexing; its support does not establish the proposed anchored barcode-end library geometry. Short 3-prime inserts also provide fewer labelable uridines. Verify junction orientation, UMI linkage and sensitivity at a fixed false-new rate with defined labeled/unlabeled RNAs."
        },
        {
          "id": "age_pairing_flow",
          "target": "flow:proposal:rna_age_encoding:f_partition_to_reporter_supernatants",
          "claim": "Before molecular indexing, reporter transfer preserves the source cell relationship through the recorded paired physical wells.",
          "verdict": "not_found",
          "literature_refs": [],
          "atlas_refs": [],
          "reason": "The relevant carrier here is the source-to-daughter map, not a reporter barcode that has yet to be copied. No retrieved experiment measures misrouting for this design. Neighboring empty wells, swapped transfer patterns and independently identifiable cells must establish the error rate; successful reporter amplification alone is insufficient."
        },
        {
          "id": "age_bst3_competitor",
          "target": "operation:proposal:rna_age_encoding:rna_copy",
          "claim": "A Bst3/random-primer second-strand improvement is already reported and cannot itself be claimed as the proposed invention.",
          "verdict": "supported_in_cited_setting",
          "literature_refs": [
            {
              "source_id": "literature:aa87bea57dc1d035cf42274b9893c67d950b077aa11c1644190d9f35d0a71f94",
              "content_sha256": "da11c22dfc2ccefe3276c7ef1642717a1b3360e8c1f15373e915bcae11d1ceba",
              "locator": "[b00008], [b00010]-[b00015], direct comparative results",
              "quote": "Bst3"
            }
          ],
          "atlas_refs": [],
          "reason": "The captured scNT-seq2 bioRxiv preprint directly compares Bst3 plus redesigned primers with the original Klenow/N9 arrangement in labeled K562 cells, reporting library-complexity and background improvements. This competes on RNA yield/fidelity, but establishes neither transfer to IAA/H reporters nor the candidate library layout. Captured version: DOI 10.1101/2025.06.03.657745, preprint version 1."
        }
      ],
      "closest_priors": [
        {
          "title": "CITE-seq: Simultaneous epitope and transcriptome measurement in single cells",
          "atlas_refs": [
            {
              "record_id": "cite_seq",
              "extraction_sha256": "3316ec994882191444a4d6ab13edaf3f97562e4d9ca00642b6f061000a34b824",
              "node_id": "illumina:cite_seq:operation:lyse_capture"
            }
          ],
          "literature_refs": [],
          "overlap": "Already measures ordinary mRNA and antibody-defined surface identity with a shared cell code and independently adjustable sequencing libraries.",
          "residual_difference": "It does not chemically distinguish a synthesis window in the inspected atlas/captured manuscript. Both candidates replace shared reporter capture with a custom early split. CITE-seq full-text origin is unresolved here; atlas identifiers and imported wording support a limited component comparison, not the proposed interfaces."
        },
        {
          "title": "NASC-seq monitors RNA synthesis in single cells",
          "atlas_refs": [],
          "literature_refs": [
            {
              "source_id": "literature:f211796a4c3f6f48c7509dfe12d800a9092bed29306c869b5ec9756f4ba98161",
              "content_sha256": "e5afe60a5de458ca2d7885128684e086beaeef791b0036abb2b36c6a5072c4a8",
              "locator": "[b00010] and [b00040]",
              "quote": "NASC-seq"
            }
          ],
          "overlap": "Already performs plate-isolated single-cell 4sU alkylation on bead-captured RNA and conventional DNA sequencing.",
          "residual_difference": "The proposed H-reporter split, pre-IAA washes, shared paired-well code and anchored UMI library are untested additions. Its readout is probabilistic recent-RNA recovery, not exact transcript birth."
        },
        {
          "title": "A combined approach for single-cell mRNA and intracellular protein expression analysis",
          "atlas_refs": [],
          "literature_refs": [
            {
              "source_id": "literature:b11de11cb22f3fbe80101ed276f64a570e8beed88591187022b6a0a9d30653bc",
              "content_sha256": "f594b6ea032669623778f0c7b6f51ff9f8f50b5b653ee43400b316a97ab15d28",
              "locator": "[b00008]-[b00009]",
              "quote": "supernatant"
            }
          ],
          "overlap": "Already partitions oligo-dT-bound mRNA and protein-containing supernatant from the same single cell.",
          "residual_difference": "Its protein assay is intracellular proximity extension with qPCR in this study. It does not implement H-DNA routing, metabolic RNA encoding or matched antibody-surface sequencing."
        },
        {
          "title": "Highly sensitive and scalable time-resolved RNA sequencing in single cells with scNT-seq2 (captured bioRxiv preprint version 1)",
          "atlas_refs": [],
          "literature_refs": [
            {
              "source_id": "literature:aa87bea57dc1d035cf42274b9893c67d950b077aa11c1644190d9f35d0a71f94",
              "content_sha256": "da11c22dfc2ccefe3276c7ef1642717a1b3360e8c1f15373e915bcae11d1ceba",
              "locator": "[b00008]-[b00015]",
              "quote": "Bst3"
            }
          ],
          "overlap": "Already changes second-strand polymerase/primer design to improve conversion-based single-cell RNA information.",
          "residual_difference": "No surface-reporter split is established; transfer of its reported K562 gains to either candidate is untested. The exact captured version is a preprint, DOI 10.1101/2025.06.03.657745."
        },
        {
          "title": "Parallel analysis of tri-molecular biosynthesis with cell identity and function in single cells",
          "atlas_refs": [],
          "literature_refs": [
            {
              "source_id": "literature:d473991d5c244a8d4423457ce5c0f4f74e19abaa6d25dae86283aca5f39dfc5a",
              "content_sha256": "81c59a3fcda7c7204b28b518598dc7088db348d785e649e9ea0f7f9f0ce44b28",
              "locator": "[b00031]-[b00035], [b00042]",
              "quote": "SOM3B"
            }
          ],
          "overlap": "SOM3B already measures de novo RNA biosynthesis together with immune surface phenotype in the same mass-cytometry events.",
          "residual_difference": "Its RNA readout is aggregate analog incorporation, not gene-resolved sequencing; it supplies no sequencing readout. The paper suggests future CITE-seq combination rather than demonstrating it."
        }
      ],
      "coverage_limitations": [
        "No exact completed same-cell synthesis-window RNA plus surface-protein sequencing implementation was established by these bounded searches; no absence or novelty conclusion follows. Optical protein measurements remain allowed by the original request and were considered through SOM3B/spinDrop and index-sorting searches.",
        "CITE-seq full-text acquisition failed; its imported manuscript and bounded atlas node were inspected. The incorrect disulfide paragraph locator requires correction. The complete custom covalent conjugate is not supported by that passage.",
        "No wet-lab data establish H selectivity, reductant clearance, effects on surface epitopes, barcode-end library yield or correctly paired informative molecules per input cell. DTT-to-IAA compatibility and RNA-bead retention need direct testing.",
        "Not every routine graph target was individually audited. Checks concentrate on central measurement, all proposed changes and material attribution/chemistry interfaces; unreviewed records do not inherit positive support.",
        "The captured scNT-seq2 source is preprint version 1. Later peer-reviewed versions were not established; its reported performance is source-setting evidence, not independent replication."
      ]
    },
    {
      "candidate_id": "physical_rna_selection",
      "candidate_sha256": "c20773778d6248fb81b105d3069fd69421e10cb02594197355b4ac707d4b2b23",
      "checks": [
        {
          "id": "selection_joint",
          "target": "candidate",
          "claim": "Early reporter routing plus off-cell EU labeling and pooled hybrid selection yields correctly paired recent RNA and surface-target identities with a net gain per sequencing budget.",
          "verdict": "transfer_not_established",
          "literature_refs": [
            {
              "source_id": "literature:bd55330ab7e7483afec0fc03034bf4b998e32f8bcc53e0ebbee39a6d51f27e1f",
              "content_sha256": "c49e993f3047d410507d7439414a7529fc09a77ca7c6b4d19641de570c6e0527",
              "locator": "[b00017] versus [b00031] and [b00072]",
              "quote": "without sorting"
            },
            {
              "source_id": "literature:d473991d5c244a8d4423457ce5c0f4f74e19abaa6d25dae86283aca5f39dfc5a",
              "content_sha256": "81c59a3fcda7c7204b28b518598dc7088db348d785e649e9ea0f7f9f0ce44b28",
              "locator": "[b00031]-[b00035], phenotype and biosynthesis",
              "quote": "SOM3B"
            }
          ],
          "atlas_refs": [
            {
              "record_id": "cite_seq",
              "extraction_sha256": "3316ec994882191444a4d6ab13edaf3f97562e4d9ca00642b6f061000a34b824",
              "node_id": "illumina:cite_seq:operation:lyse_capture"
            }
          ],
          "reason": "scEU-seq and spinDrop establish sequence-based recovery of EU-selected single-cell RNA; CITE-seq establishes surface reporters. Their components do not demonstrate this proposed same-cell interface. spinDrop showed surface-antibody sorting and EU sequencing in separate experiments, explicitly omitting sorting for the EU experiment. SOM3B already pairs biosynthesis with immunophenotype by mass cytometry. None of those observations establishes the proposed full sequencing coassay or its gain."
        },
        {
          "id": "selection_route_change",
          "target": "change:ps_change_reporter_route",
          "claim": "Orthogonal reporter docking/copying on non-biotin support before RNA chemistry improves joint informative recovery over shared capture.",
          "verdict": "not_found",
          "literature_refs": [
            {
              "source_id": "literature:b11de11cb22f3fbe80101ed276f64a570e8beed88591187022b6a0a9d30653bc",
              "content_sha256": "f594b6ea032669623778f0c7b6f51ff9f8f50b5b653ee43400b316a97ab15d28",
              "locator": "[b00008], Fig. 1a",
              "quote": "supernatant"
            }
          ],
          "atlas_refs": [
            {
              "record_id": "cite_seq",
              "extraction_sha256": "3316ec994882191444a4d6ab13edaf3f97562e4d9ca00642b6f061000a34b824",
              "node_id": "illumina:cite_seq:operation:lyse_capture"
            }
          ],
          "reason": "CITE-seq demonstrates shared poly(A) capture; SPARC shows early same-cell fractionation is already an experimental design move. No inspected source tests this reporter-tail/support arrangement or proves the proposed unbranched RNA chemistry harms reporters. The engineering difference is real, but the benefit is conditional and must include RNA loss, cell attrition, reporter leakage and all library reads in its denominator."
        },
        {
          "id": "selection_order_change",
          "target": "change:ps_change_selection_order",
          "claim": "Moving RNA cleanup/click from fixed cells to isolated RNA daughters preserves enough label-linked single-cell molecules to justify reporter isolation.",
          "verdict": "transfer_not_established",
          "literature_refs": [
            {
              "source_id": "literature:4a22f20f2523877c5ada4c6a696f57de6dc6a7218c0e75ae4177d01ff5e28b44",
              "content_sha256": "0b5b3bf6cc47c4bf6395d4ef9a9464e3e106ef13a279373698c4fa7c6f1bc0fe",
              "locator": "Page 1, paragraph beginning To measure newly synthesized transcripts",
              "quote": "biotinylated in situ"
            },
            {
              "source_id": "literature:6e608d6c0ae76c4a883c188c319655aecb25a8cfd70649ee4d69c2448bd0996d",
              "content_sha256": "85477d2a4e231da9e94c622193645fe6bd63b42950f7064c84859e16b6e434b3",
              "locator": "Materials and methods, Detection of nascent transcripts; characters 12591-13100",
              "quote": "azide-modified biotin"
            }
          ],
          "atlas_refs": [],
          "reason": "scEU-seq clicks in fixed/permeabilized cells before sorting; spinDrop retains that pre-processing order. Independent primary Methods show click biotinylation on isolated RNA in a bulk qPCR assay, so off-cell chemistry is a supported component, not invented chemistry. That does not establish picogram-scale cleanup, hybrid retention or same-cell protein compatibility after this new routing order."
        },
        {
          "id": "selection_route_op",
          "target": "operation:ps_route",
          "claim": "Cell-coded docking beads selectively capture and copy released antibody DNA while leaving sufficiently intact RNA in the mapped daughter.",
          "verdict": "transfer_not_established",
          "literature_refs": [
            {
              "source_id": "literature:b11de11cb22f3fbe80101ed276f64a570e8beed88591187022b6a0a9d30653bc",
              "content_sha256": "f594b6ea032669623778f0c7b6f51ff9f8f50b5b653ee43400b316a97ab15d28",
              "locator": "[b00008], Fig. 1a",
              "quote": "supernatant"
            }
          ],
          "atlas_refs": [
            {
              "record_id": "cite_seq",
              "extraction_sha256": "3316ec994882191444a4d6ab13edaf3f97562e4d9ca00642b6f061000a34b824",
              "node_id": "illumina:cite_seq:operation:lyse_capture"
            }
          ],
          "reason": "Indexed antibody-DNA copying has a CITE-seq precedent and same-cell physical separation has a SPARC precedent. Neither demonstrates the candidate substrate partition, non-biotin support, RNA exclusion or copying multiplicity. RNA retention and nonspecific bead adsorption require mass-balance controls. UMI labels added on each copying event do not automatically give original reporter or protein molecule counts."
        },
        {
          "id": "selection_capture_geometry",
          "target": "state_property:ps_kit:capture_primer",
          "claim": "The covalently anchored docking-complement primer has an extendable end and copies both target identity and its cell code in the intended orientation.",
          "verdict": "not_found",
          "literature_refs": [],
          "atlas_refs": [],
          "reason": "The proposed sequence/support geometry was not demonstrated by the inspected papers. A familiar polymerase and a complementary sequence alone do not establish access at a bead surface, full-length copying, soluble product release or suppression of repeated copying. Test the exact oligonucleotide/linker design with known templates and read the product junctions."
